use std::ffi::CStr;

use crate::bindings::*;
use crate::domain::core::{Code, Error};

mod table {
    // Generated by build.rs from agc_types.h: (rc, name, message).
    include!(concat!(env!("OUT_DIR"), "/rc_table.rs"));
}

/// Everything an export can fail with: an error from the layers below, or a
/// problem with how the C caller called us. This is the only place that turns
/// errors into `agc_rc`, as `ToStatusError` is in the Go server.
#[derive(Debug)]
pub enum FfiError {
    Domain(Error),
    InvalidArgument(String),
    AbiMismatch(&'static str),
    BufferTooSmall { needed: usize },
    NotImplemented(&'static str),
    /// The normal end of a listing.
    IteratorExhausted,
}

impl From<Error> for FfiError {
    fn from(e: Error) -> Self {
        FfiError::Domain(e)
    }
}

impl FfiError {
    pub fn invalid(message: impl Into<String>) -> Self {
        FfiError::InvalidArgument(message.into())
    }

    pub fn rc(&self) -> agc_rc {
        match self {
            FfiError::Domain(e) => code_rc(e.code()),
            FfiError::InvalidArgument(_) => AGC_ERR_INVALID_ARGUMENT,
            FfiError::AbiMismatch(_) => AGC_ERR_ABI_MISMATCH,
            FfiError::BufferTooSmall { .. } => AGC_ERR_BUFFER_TOO_SMALL,
            FfiError::NotImplemented(_) => AGC_ERR_NOT_IMPLEMENTED,
            FfiError::IteratorExhausted => AGC_ERR_ITERATOR_EXHAUSTED,
        }
    }

    /// What `agc_last_error` reports. Domain errors give only their own
    /// message, not the operation, which names Rust internals.
    pub fn message(&self) -> String {
        match self {
            FfiError::Domain(e) => e.message().to_owned(),
            FfiError::InvalidArgument(m) => m.clone(),
            FfiError::AbiMismatch(what) => format!("{what}: struct_size is not one this library accepts"),
            FfiError::BufferTooSmall { needed } => format!("storage too small: {needed} bytes needed"),
            FfiError::NotImplemented(what) => format!("{what} is not implemented"),
            FfiError::IteratorExhausted => "no more items".to_owned(),
        }
    }
}

fn code_rc(code: Code) -> agc_rc {
    match code {
        Code::InvalidArgument => AGC_ERR_INVALID_ARGUMENT,
        Code::AlreadyExists => AGC_ERR_ALREADY_EXISTS,
        Code::KeyNotFound => AGC_ERR_CRYPTO_KEY_NOT_FOUND,
        Code::TemplateNotFound => AGC_ERR_CRYPTO_TEMPLATE_NOT_FOUND,
        Code::TemplateDeprecated => AGC_ERR_CRYPTO_TEMPLATE_DEPRECATED,
        Code::TemplateForbidden => AGC_ERR_CRYPTO_TEMPLATE_FORBIDDEN,
        Code::NoMatchingTemplate => AGC_ERR_CRYPTO_NO_MATCHING_TEMPLATE,
        Code::PolicyNotFound => AGC_ERR_CRYPTO_POLICY_NOT_FOUND,
        Code::ProviderNotFound => AGC_ERR_CRYPTO_PROVIDER_NOT_FOUND,
        Code::ProviderIncompatible => AGC_ERR_CRYPTO_PROVIDER_INCOMPATIBLE,
        Code::NoMatchingProvider => AGC_ERR_CRYPTO_NO_MATCHING_PROVIDER,
        Code::InsufficientEntropy => AGC_ERR_CRYPTO_INSUFFICIENT_ENTROPY,
        Code::KeyOperationNotAllowed => AGC_ERR_CRYPTO_KEY_OPERATION_NOT_ALLOWED,
        Code::ConcurrentAccess => AGC_ERR_CRYPTO_CONCURRENT_ACCESS,
        Code::IncompatibleParameters => AGC_ERR_CRYPTO_INCOMPATIBLE_PARAMETERS,
        Code::MigrationNotFeasible => AGC_ERR_CRYPTO_MIGRATION_NOT_FEASIBLE,
        Code::KeyNotExtractable => AGC_ERR_CRYPTO_KEY_NOT_EXTRACTABLE,
        Code::NotImplemented => AGC_ERR_NOT_IMPLEMENTED,
        Code::PolicyViolation => AGC_ERR_CRYPTO_POLICY_VIOLATION,
        Code::Internal => AGC_ERR_INTERNAL,
    }
}

/// `AGC_ERR_CRYPTO_*` codes are -(1000 + wire value) of caas.crypto.v1's
/// CryptoErrorCode (agc_types.h); everything above is local to this library.
pub fn is_crypto_rc(rc: agc_rc) -> bool {
    rc <= AGC_ERR_CRYPTO_UNSPECIFIED
}

pub fn rc_name(rc: agc_rc) -> Option<&'static CStr> {
    table::RC_TABLE.iter().find(|(r, _, _)| *r == rc).map(|(_, name, _)| *name)
}

pub fn rc_message(rc: agc_rc) -> Option<&'static CStr> {
    table::RC_TABLE.iter().find(|(r, _, _)| *r == rc).map(|(_, _, message)| *message)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_domain_code_has_its_own_rc() {
        let codes = [
            Code::InvalidArgument,
            Code::AlreadyExists,
            Code::KeyNotFound,
            Code::TemplateNotFound,
            Code::TemplateDeprecated,
            Code::TemplateForbidden,
            Code::NoMatchingTemplate,
            Code::PolicyNotFound,
            Code::ProviderNotFound,
            Code::ProviderIncompatible,
            Code::NoMatchingProvider,
            Code::InsufficientEntropy,
            Code::KeyOperationNotAllowed,
            Code::ConcurrentAccess,
            Code::IncompatibleParameters,
            Code::MigrationNotFeasible,
            Code::KeyNotExtractable,
            Code::NotImplemented,
            Code::PolicyViolation,
            Code::Internal,
        ];
        let mut rcs: Vec<_> = codes.iter().map(|&c| code_rc(c)).collect();
        rcs.sort();
        rcs.dedup();
        assert_eq!(rcs.len(), codes.len());
        assert!(rcs.iter().all(|&rc| rc_name(rc).is_some()), "every mapped rc must be a header code");
    }

    #[test]
    fn table_has_names_and_messages_from_the_header() {
        assert_eq!(rc_name(AGC_OK as agc_rc), Some(c"AGC_OK"));
        assert_eq!(rc_message(AGC_OK as agc_rc), Some(c"success"));
        assert_eq!(rc_name(AGC_ERR_BUFFER_TOO_SMALL), Some(c"AGC_ERR_BUFFER_TOO_SMALL"));
        assert_eq!(rc_message(AGC_ERR_BUFFER_TOO_SMALL), Some(c"out_len holds the required size"));
        assert_eq!(rc_message(AGC_ERR_CRYPTO_KEY_NOT_FOUND), Some(c"key not found"));
        assert_eq!(rc_name(12345), None);
    }

    #[test]
    fn crypto_range() {
        assert!(is_crypto_rc(AGC_ERR_CRYPTO_UNSPECIFIED));
        assert!(is_crypto_rc(AGC_ERR_CRYPTO_KEY_NOT_FOUND));
        assert!(!is_crypto_rc(AGC_ERR_ITERATOR_EXHAUSTED));
    }
}
